//initMouseWheel += new MouseEventHandler(ZoomInOut);OriginalSize = Size.Clone();#region ZOOM-IN-OUTprivate Size OriginalSize = new Size(100, 100);private float CurrentScale = 1.0f;public void ZoomInOut(object sender, MouseEventArgs e) {	// The amount by which we adjust scale per wheel click.	const float scale_per_delta = 0.1f / 120;	// Update the drawing based upon the mouse wheel scrolling.	CurrentScale += e.Delta * scale_per_delta;	if (CurrentScale < 0) CurrentScale = 0;	// Scale the control	var newSize = new Size(		(int)(OriginalSize.Width * CurrentScale),		(int)(OriginalSize.Height * CurrentScale)	);	MinimumSize = newSize;	Size = newSize;	// Fit image	var imageSize = new Size(Size.Width - ImageMargin, Size.Height - ImageMargin);	IconSprite.Image = ISprite.AsImage().ResizeImage(imageSize);	// move IconChain middle right	IconChain.Location = new Point(		 Width - IconChain.Width - BorderThickness * 2,		 Height - IconChain.Height - BorderThickness * 2	 );	Console.WriteLine("RulesBoxControl > ZoomInOut > Percent scale:{0}", CurrentScale.ToString("p0"));}#endregion//ORprivate double ZOOMFACTOR = 1.25;   // = 25% smaller or largerprivate int MINMAX = 5;             // 5 times bigger or smaller than the ctrlpublic void ZoomInOut(object sender, MouseEventArgs e) {	if (e.Delta < 0) {		ZoomIn();	} else {		ZoomOut();	}}/// <summary>/// Make the PictureBox dimensions larger to effect the Zoom./// </summary>/// <remarks>Maximum 5 times bigger</remarks>private void ZoomIn() {	if ((IconSprite.Image.Width < (MINMAX * Width)) &&		(IconSprite.Image.Height < (MINMAX * Height))) {		var imageSize = new Size(			Convert.ToInt32(IconSprite.Image.Width * ZOOMFACTOR),			Convert.ToInt32(IconSprite.Image.Height * ZOOMFACTOR)		);		IconSprite.Image = ISprite.AsImage().ResizeImage(imageSize);		// fit control to image bounds		Size = new Size( imageSize.Width, imageSize.Height );		// move IconChain middle right		IconChain.Location = new Point(			 Width - IconChain.Width - BorderThickness * 2,			 Height - IconChain.Height - BorderThickness * 2		 );	}}/// <summary>/// Make the PictureBox dimensions smaller to effect the Zoom./// </summary>/// <remarks>Minimum 5 times smaller</remarks>private void ZoomOut() {	if ((IconSprite.Image.Width > (Width / MINMAX)) &&		(IconSprite.Image.Height > (Height / MINMAX))) {		var imageSize = new Size(			Convert.ToInt32(IconSprite.Image.Width / ZOOMFACTOR),			Convert.ToInt32(IconSprite.Image.Height / ZOOMFACTOR)		);		IconSprite.Image = ISprite.AsImage().ResizeImage(imageSize);		// fit control to image bounds		Size = new Size(imageSize.Width, imageSize.Height);		// move IconChain middle right		IconChain.Location = new Point(			 Width - IconChain.Width - BorderThickness * 2,			 Height - IconChain.Height - BorderThickness * 2		 );	}}